import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {[number, number, number]} position
 * @property {[number, number, number]} rotation
 * @property {[number, number, number]} scale
 * @property {{imageUrl?:string,depthMapUrl?:string}} assets
 * @property {{name:string,params:any}[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {{[key:string]:(target:import('three').Object3D, params:any)=>void}} primitives
 * @property {(event:string)=>void} emit
 */

/**
 * Creates a parallax‑plane pricing row node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------
  // Load textures
  // -----------------------------------------------------------------
  const colorTex = ctx.textureLoader(config.assets?.imageUrl ?? '');
  const depthTex = ctx.textureLoader(config.assets?.depthMapUrl ?? '');

  // -----------------------------------------------------------------
  // Geometry & Material (node‑based)
  // -----------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  const material = new MeshStandardNodeMaterial({
    map: colorTex,
    displacementMap: depthTex,
    displacementScale: 0.12, // subtle depth
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    // optional rim accent via emissive (scaled with accent colour)
    emissive: 0x0,
    side: 2, // DoubleSide
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(...config.position);
  mesh.rotation.set(...config.rotation);
  mesh.scale.set(...config.scale);

  // -----------------------------------------------------------------
  // Apply cinematic primitives declared in config
  // -----------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    }
  }

  // -----------------------------------------------------------------
  // Interaction handlers (stored in userData)
  // -----------------------------------------------------------------
  const handlers = {};

  // Hover – rise‑in effect (subtle 0.15 scene units)
  const hoverTL = gsap.timeline({ paused: true });
  const baseY = mesh.position.y;
  hoverTL.to(
    mesh.position,
    {
      y: baseY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    },
    0
  );

  handlers.hover = {
    enter() {
      hoverTL.play();
    },
    leave() {
      hoverTL.reverse();
    },
  };

  // Click – emit navigation event
  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-pricing.select');
    }
  };

  // Store handlers
  mesh.userData.handlers = handlers;

  // -----------------------------------------------------------------
  // Data binding (declarative, stored for external system)
  // -----------------------------------------------------------------
  mesh.userData.binding = {
    source: 'trpc.visits.book.slot',
    target: 'confirmPanel',
  };

  // -----------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------
  mesh.userData.cleanup = () => {
    hoverTL.kill();
    geometry.dispose();
    material.dispose();
    if (colorTex && typeof colorTex.dispose === 'function') colorTex.dispose();
    if (depthTex && typeof depthTex.dispose === 'function') depthTex.dispose();
    // Remove references
    mesh.userData.handlers = null;
    mesh.userData.binding = null;
    mesh.userData.cleanup = null;
  };

  return mesh;
}
